struct semaphore { int value; queue waiters; };

P(S) { // 整个更新与排队动作必须原子完成
    S.value--;
    if (S.value < 0) {
        把当前进程加入 S.waiters;
        block();
    }
}
V(S) {
    S.value++;
    if (S.value <= 0) {
        从 S.waiters 取一个等待进程;
        wakeup(该进程);
    }
}

